{
  "outcome": "patch",
  "candidate_reviews": {
    "C001": {
      "decision": "edit",
      "reason": "Construction of sample uses old property SpeedMps which must be renamed to GroundSpeedMps per new schema"
    },
    "C002": {
      "decision": "edit",
      "reason": "Observation dictionary key 'speed_mps' must be renamed to 'ground_speed_mps' per intended_behavior"
    },
    "C003": {
      "decision": "edit",
      "reason": "Speeding predicate uses entity.SpeedMps which must be renamed to entity.GroundSpeedMps per new schema"
    }
  },
  "edits": [
    {
      "before": "            var sample = new Simulation.Telemetry.VehicleTelemetry { VehicleId = request.VehicleId, SpeedMps = request.Speed };\n",
      "after": "            var sample = new Simulation.Telemetry.VehicleTelemetry { VehicleId = request.VehicleId, GroundSpeedMps = request.Speed };\n"
    },
    {
      "before": "            var fields = new Dictionary<string, object> { [\"vehicle_id\"] = entity.VehicleId, [\"speed_mps\"] = entity.SpeedMps };\n",
      "after": "            var fields = new Dictionary<string, object> { [\"vehicle_id\"] = entity.VehicleId, [\"ground_speed_mps\"] = entity.GroundSpeedMps };\n"
    },
    {
      "before": "            return new { fields, speeding = entity.SpeedMps > 30.0, constructed_payload = Convert.ToBase64String(sample.ToByteArray()) };\n",
      "after": "            return new { fields, speeding = entity.GroundSpeedMps > 30.0, constructed_payload = Convert.ToBase64String(sample.ToByteArray()) };\n"
    }
  ],
  "rationale": "Schema change renames field speed_mps to ground_speed_mps on wire field 2. This requires updating: (1) the sample construction property from SpeedMps to GroundSpeedMps, (2) the observation key from 'speed_mps' to 'ground_speed_mps', and (3) the speeding predicate from entity.SpeedMps to entity.GroundSpeedMps. The threshold > 30.0 and vehicle_id remain unchanged as specified.",
  "confidence": 0.95,
  "assumptions": [
    "Protobuf C# bindings will generate property named GroundSpeedMps for the renamed field",
    "The runtime dictionary key must match the new wire field name 'ground_speed_mps'",
    "All three occurrences of SpeedMps must be consistently renamed to GroundSpeedMps"
  ]
}
